#include <Native/SoundStreamFilename.hpp>
#include "assets.hpp"
#include <JSystem/JAudio2/JAUSoundTable.hpp>
#include <fstream>
#include <cstdio>
template<class Root,class Section,class Group,class Item> void verify(const char* path,bool named){std::ifstream f(path,std::ios::binary);assetCheck(bool(f),"Missing table");std::vector<u8> b((std::istreambuf_iterator<char>(f)),{});assetCheck(b.size()>=16,"Short table");u32 root=be32(b.data()+12);extent(root,4,b.size());u32 sections=be32(b.data()+root);extent(root+4,uint64_t(sections)*4,b.size());JAUSoundTable_<Root,Section,Group,Item> t;t.init(b.data());assetCheck(t.mRoot!=nullptr,"Native init failed");unsigned groups=0,items=0,streams=0;std::set<std::string> catalog;std::ifstream index(std::string(path).substr(0,std::string(path).find_last_of("/\\"))+"/asset-index.tsv");assetCheck(bool(index),"Missing disc catalog");std::string line;while(std::getline(index,line)){auto tab=line.find('\t');if(tab!=std::string::npos)catalog.insert(line.substr(0,tab));}for(u32 s=0;s<sections;++s){u32 so=be32(b.data()+root+4+s*4);if(!so){assetCheck(!t.getSection(s),"Zero section mismatch");continue;}extent(so,named?8:4,b.size());auto* section=t.getSection(s);assetCheck(reinterpret_cast<u8*>(section)==b.data()+so,"Section mismatch");u32 ng=be32(b.data()+so);u32 goBase=so+(named?8:4);extent(goBase,uint64_t(ng)*4,b.size());for(u32 g=0;g<ng;++g){u32 go=be32(b.data()+goBase+g*4);if(!go){assetCheck(!t.getGroup(section,g),"Zero group mismatch");continue;}extent(go,8,b.size());auto* group=t.getGroup(section,g);assetCheck(reinterpret_cast<u8*>(group)==b.data()+go,"Group mismatch");++groups;u32 ni=be32(b.data()+go);extent(go+8,uint64_t(ni)*4,b.size());for(u32 i=0;i<ni;++i){u32 raw=be32(b.data()+go+8+i*4),offset=named?raw:raw&0xffffff;auto* item=t.getItem(group,i);if(!offset){assetCheck(!item,"Null item mismatch");continue;}extent(offset,1,b.size());assetCheck(reinterpret_cast<u8*>(item)==b.data()+offset,"Item mismatch");if(named)assetCheck(std::find(b.begin()+offset,b.end(),0)!=b.end(),"Unterminated name");else if constexpr(std::is_same_v<Group,JAUSoundTableGroup>) assetCheck(group->getTypeID(i)==b[go+8+i*4],"Type mismatch");if(!named && (raw>>28)==7){extent(offset,8,b.size());const char* resolved=Native::soundStreamFilename(b.data(),b.size(),offset);assetCheck(resolved!=nullptr,"Bounded filename resolver rejected retail record");const u32 filename=be32(b.data()+offset+4);assetCheck(resolved==reinterpret_cast<const char*>(b.data()+filename),"Bounded filename resolver mismatch");extent(filename,1,b.size());auto end=std::find(b.begin()+filename,b.end(),0);assetCheck(end!=b.end(),"Unterminated stream filename");std::string name(reinterpret_cast<const char*>(b.data()+filename),size_t(end-(b.begin()+filename)));assetCheck(catalog.count(name)||catalog.count("/"+name),"Stream filename absent from disc catalog");++streams;}++items;}}}std::printf("PASS retail %s: %u sections, %u groups, %u non-null items\n",named?"BSTN":"BST",sections,groups,items);if(!named)std::printf("PASS retail stream filename references: %u records resolve to disc assets\n",streams);}
int main(int argc,char** argv){try{assetCheck(argc==3,"Expected BST and BSTN");verify<JAUSoundTableRoot,JAUSoundTableSection,JAUSoundTableGroup,void>(argv[1],false);verify<JAUSoundNameTableRoot,JAUSoundNameTableSection,JAUSoundNameTableGroup,char>(argv[2],true);}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}}



